UPDATE sys_file_object
SET reference_count = reference_count + 1,
    updated_by = #{operatorId}
WHERE id = #{id}
  AND storage_status = 'AVAILABLE'
  AND deleted_at = 0

UPDATE sys_file_object
SET reference_count = reference_count - 1,
    updated_by = #{operatorId}
WHERE id = #{id}
  AND reference_count > 0
  AND deleted_at = 0

UPDATE sys_file
SET deleted_at = #{deletedAt},
    updated_by = #{operatorId}
WHERE id = #{id}
  AND uploader_id = #{uploaderId}
  AND deleted_at = 0
  AND NOT EXISTS (
      SELECT 1 FROM biz_delivery_report_attachment a
      WHERE a.file_id = #{id} AND a.deleted_at = 0
  )
